CREATE TABLE public.portfolio_vinculos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fonte_tipo text NOT NULL CHECK(fonte_tipo IN('projeto','iniciativa')),fonte_id uuid NOT NULL,tipo text NOT NULL CHECK(tipo IN('objetivo','indicador')),ref_id uuid NOT NULL,origem text NOT NULL DEFAULT 'legado' CHECK(origem IN('legado','ia','manual')),status text NOT NULL DEFAULT 'proposto' CHECK(status IN('proposto','validado','removido')),justificativa text NOT NULL DEFAULT '',confianca text CHECK(confianca IN('alta','media','baixa')),proposto_por uuid,proposto_nome text,created_at timestamptz NOT NULL DEFAULT now(),validado_por uuid,validado_nome text,validado_em timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(fonte_tipo,fonte_id,tipo,ref_id),CHECK((status='validado' AND validado_por IS NOT NULL AND validado_em IS NOT NULL) OR (status<>'validado' AND validado_por IS NULL AND validado_em IS NULL)));
GRANT SELECT ON public.portfolio_vinculos TO authenticated; GRANT ALL ON public.portfolio_vinculos TO service_role;
ALTER TABLE public.portfolio_vinculos ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.portfolio_fonte_visivel(_tipo text,_id uuid) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND CASE WHEN _tipo='projeto' THEN EXISTS(SELECT 1 FROM projetos WHERE id=_id) WHEN _tipo='iniciativa' THEN EXISTS(SELECT 1 FROM mt_iniciativas WHERE id=_id) ELSE false END $$;
REVOKE ALL ON FUNCTION public.portfolio_fonte_visivel(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.portfolio_fonte_visivel(text,uuid) TO authenticated,service_role;
CREATE FUNCTION public.portfolio_pode_editar(_tipo text,_id uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT auth.uid() IS NOT NULL AND CASE WHEN _tipo='projeto' THEN public.acesso_modulo(auth.uid(),'pmo',false) AND EXISTS(SELECT 1 FROM projetos p WHERE p.id=_id AND (public.proj_gov_ou_ceo(auth.uid()) OR public.proj_principal(auth.uid(),p.id))) WHEN _tipo='iniciativa' THEN (public.acesso_modulo(auth.uid(),'okrs',false) OR public.acesso_modulo(auth.uid(),'metas',false) OR public.acesso_modulo(auth.uid(),'rotina',false) OR public.acesso_modulo(auth.uid(),'cesta',false)) AND EXISTS(SELECT 1 FROM mt_iniciativas i WHERE i.id=_id AND (public.proj_gov_ou_ceo(auth.uid()) OR i.cadeira_id=public.mt_cadeira_do_usuario(auth.uid()) OR EXISTS(SELECT 1 FROM mt_cadeiras c WHERE c.id=i.cadeira_id AND c.diretor_user_id=auth.uid()))) ELSE false END $$;
REVOKE ALL ON FUNCTION public.portfolio_pode_editar(text,uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.portfolio_pode_editar(text,uuid) TO authenticated,service_role;
CREATE POLICY ler ON public.portfolio_vinculos FOR SELECT TO authenticated USING(public.portfolio_fonte_visivel(fonte_tipo,fonte_id));
CREATE TABLE public.portfolio_vinculos_auditoria(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fonte_tipo text NOT NULL,fonte_id uuid NOT NULL,vinculo_id uuid,acao text NOT NULL,usuario_id uuid,usuario_nome text,antes jsonb,depois jsonb,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.portfolio_vinculos_auditoria TO authenticated; GRANT ALL ON public.portfolio_vinculos_auditoria TO service_role;
ALTER TABLE public.portfolio_vinculos_auditoria ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.portfolio_vinculos_auditoria FOR SELECT TO authenticated USING(public.portfolio_pode_editar(fonte_tipo,fonte_id));
CREATE FUNCTION public.portfolio_auditar() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO portfolio_vinculos_auditoria(fonte_tipo,fonte_id,vinculo_id,acao,usuario_id,usuario_nome,antes,depois) VALUES(NEW.fonte_tipo,NEW.fonte_id,NEW.id,CASE WHEN TG_OP='INSERT' THEN 'propor' WHEN NEW.status='removido' THEN 'remover' WHEN NEW.status='validado' AND OLD.status='proposto' THEN 'validar' ELSE 'editar' END,coalesce(auth.uid(),NEW.proposto_por),coalesce(NEW.validado_nome,NEW.proposto_nome),CASE WHEN TG_OP='UPDATE' THEN to_jsonb(OLD) END,to_jsonb(NEW)); RETURN NEW; END $$;
CREATE TRIGGER auditar AFTER INSERT OR UPDATE ON public.portfolio_vinculos FOR EACH ROW EXECUTE FUNCTION public.portfolio_auditar();
CREATE FUNCTION public.portfolio_revisar(_itens jsonb,_acao text) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; v portfolio_vinculos%ROWTYPE; ft text; fid uuid; t text; r uuid; nome text; n integer:=0; BEGIN IF _acao IS NULL OR _acao NOT IN('validar','salvar','remover') OR _itens IS NULL OR jsonb_typeof(_itens)<>'array' OR jsonb_array_length(_itens) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Seleção inválida (1–100).'; END IF; SELECT display_name INTO nome FROM profiles WHERE user_id=auth.uid(); nome:=coalesce(nome,'Usuário autorizado'); FOR x IN SELECT value FROM jsonb_array_elements(_itens) ORDER BY value->>'fonte_tipo',value->>'fonte_id',value->>'id' LOOP ft:=x->>'fonte_tipo'; fid:=(x->>'fonte_id')::uuid; IF NOT coalesce(public.portfolio_pode_editar(ft,fid),false) THEN RAISE EXCEPTION 'Sem permissão para este item.'; END IF; IF ft='projeto' THEN PERFORM 1 FROM projetos WHERE id=fid FOR UPDATE; ELSE PERFORM 1 FROM mt_iniciativas WHERE id=fid FOR UPDATE; END IF; v:=NULL; IF x->>'id' IS NOT NULL THEN SELECT * INTO v FROM portfolio_vinculos WHERE id=(x->>'id')::uuid AND fonte_tipo=ft AND fonte_id=fid FOR UPDATE; IF NOT FOUND OR v.status='removido' THEN RAISE EXCEPTION 'Vínculo indisponível.'; END IF; END IF; t:=coalesce(x->>'tipo',v.tipo); r:=coalesce((x->>'ref_id')::uuid,v.ref_id); IF _acao='remover' THEN IF v.id IS NULL THEN RAISE EXCEPTION 'Vínculo inexistente.'; END IF; UPDATE portfolio_vinculos SET status='removido',validado_por=NULL,validado_nome=NULL,validado_em=NULL,updated_at=now() WHERE id=v.id; ELSE IF NOT coalesce(public.estrategia_alvo_ativo(t,r),false) THEN RAISE EXCEPTION 'Alvo inativo ou fora do semestre vigente.'; END IF; IF _acao='validar' THEN IF v.id IS NULL OR v.status<>'proposto' THEN RAISE EXCEPTION 'Selecione apenas vínculos propostos.'; END IF; UPDATE portfolio_vinculos SET status='validado',validado_por=auth.uid(),validado_nome=nome,validado_em=now(),updated_at=now() WHERE id=v.id; ELSE IF v.id IS NOT NULL AND (v.tipo<>t OR v.ref_id<>r) THEN UPDATE portfolio_vinculos SET status='removido',validado_por=NULL,validado_nome=NULL,validado_em=NULL,updated_at=now() WHERE id=v.id; END IF; INSERT INTO portfolio_vinculos(fonte_tipo,fonte_id,tipo,ref_id,origem,status,justificativa,proposto_por,proposto_nome,validado_por,validado_nome,validado_em) VALUES(ft,fid,t,r,'manual','validado',left(coalesce(x->>'justificativa','Vínculo manual'),1000),auth.uid(),nome,auth.uid(),nome,now()) ON CONFLICT(fonte_tipo,fonte_id,tipo,ref_id) DO UPDATE SET origem='manual',status='validado',justificativa=EXCLUDED.justificativa,validado_por=auth.uid(),validado_nome=nome,validado_em=now(),updated_at=now(); END IF; END IF; n:=n+1; END LOOP; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.portfolio_revisar(jsonb,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.portfolio_revisar(jsonb,text) TO authenticated;
CREATE TABLE public.portfolio_vinculacao_jobs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),fonte_tipo text NOT NULL CHECK(fonte_tipo IN('projeto','iniciativa')),fonte_id uuid NOT NULL,criado_por uuid,status text NOT NULL DEFAULT 'pendente' CHECK(status IN('pendente','executando','concluido','erro','pausado')),erro text,bloqueio text,run_id text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(fonte_tipo,fonte_id));
GRANT SELECT ON public.portfolio_vinculacao_jobs TO authenticated; GRANT ALL ON public.portfolio_vinculacao_jobs TO service_role;
ALTER TABLE public.portfolio_vinculacao_jobs ENABLE ROW LEVEL SECURITY;
CREATE POLICY ler ON public.portfolio_vinculacao_jobs FOR SELECT TO authenticated USING((criado_por=auth.uid() OR public.proj_gov_ou_ceo(auth.uid())) AND public.portfolio_fonte_visivel(fonte_tipo,fonte_id));
CREATE FUNCTION public.portfolio_novo_item() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN INSERT INTO portfolio_vinculacao_jobs(fonte_tipo,fonte_id,criado_por) VALUES(CASE WHEN TG_TABLE_NAME='projetos' THEN 'projeto' ELSE 'iniciativa' END,NEW.id,coalesce(auth.uid(),NEW.created_by)) ON CONFLICT DO NOTHING; RETURN NEW; END $$;
CREATE TRIGGER portfolio_novo AFTER INSERT ON public.projetos FOR EACH ROW EXECUTE FUNCTION public.portfolio_novo_item();
CREATE TRIGGER portfolio_novo AFTER INSERT ON public.mt_iniciativas FOR EACH ROW EXECUTE FUNCTION public.portfolio_novo_item();
INSERT INTO portfolio_vinculos(fonte_tipo,fonte_id,tipo,ref_id,origem,justificativa,proposto_por) SELECT 'projeto',projeto_id,CASE WHEN tipo='bsc_objetivo' THEN 'objetivo' ELSE 'indicador' END,ref_id,'legado','Vínculo existente do projeto',criado_por FROM projeto_vinculos WHERE public.estrategia_alvo_ativo(CASE WHEN tipo='bsc_objetivo' THEN 'objetivo' ELSE 'indicador' END,ref_id) ON CONFLICT DO NOTHING;
INSERT INTO portfolio_vinculos(fonte_tipo,fonte_id,tipo,ref_id,origem,justificativa) SELECT 'iniciativa',iniciativa_id,CASE WHEN tipo='objetivo' THEN 'objetivo' ELSE 'indicador' END,ref_id,'legado','Vínculo existente da iniciativa' FROM mt_acao_vinculos WHERE tipo<>'projeto' AND public.estrategia_alvo_ativo(CASE WHEN tipo='objetivo' THEN 'objetivo' ELSE 'indicador' END,ref_id) ON CONFLICT DO NOTHING;
CREATE FUNCTION public.portfolio_gravar_propostas(_fonte_tipo text,_fonte_id uuid,_usuario uuid,_propostas jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE x jsonb; n integer:=0; nome text; BEGIN IF _fonte_tipo='projeto' THEN PERFORM 1 FROM projetos WHERE id=_fonte_id FOR UPDATE; ELSIF _fonte_tipo='iniciativa' THEN PERFORM 1 FROM mt_iniciativas WHERE id=_fonte_id FOR UPDATE; ELSE RAISE EXCEPTION 'Fonte inválida'; END IF; IF NOT FOUND THEN RAISE EXCEPTION 'Fonte inexistente'; END IF; IF EXISTS(SELECT 1 FROM portfolio_vinculos WHERE fonte_tipo=_fonte_tipo AND fonte_id=_fonte_id AND status='validado') THEN RETURN 0; END IF; IF _propostas IS NULL OR jsonb_typeof(_propostas)<>'array' OR jsonb_array_length(_propostas)>100 THEN RAISE EXCEPTION 'Propostas inválidas'; END IF; SELECT display_name INTO nome FROM profiles WHERE user_id=_usuario; FOR x IN SELECT value FROM jsonb_array_elements(_propostas) LOOP IF x->>'origem' NOT IN('ia','legado') OR NOT public.estrategia_alvo_ativo(x->>'tipo',(x->>'ref_id')::uuid) THEN RAISE EXCEPTION 'Proposta inválida ou alvo inativo'; END IF; INSERT INTO portfolio_vinculos(fonte_tipo,fonte_id,tipo,ref_id,origem,status,justificativa,confianca,proposto_por,proposto_nome) VALUES(_fonte_tipo,_fonte_id,x->>'tipo',(x->>'ref_id')::uuid,x->>'origem','proposto',left(coalesce(x->>'justificativa',''),1000),x->>'confianca',_usuario,nome) ON CONFLICT DO NOTHING; END LOOP; RETURN (SELECT count(*)::int FROM portfolio_vinculos WHERE fonte_tipo=_fonte_tipo AND fonte_id=_fonte_id AND status='proposto'); END $$;
REVOKE ALL ON FUNCTION public.portfolio_gravar_propostas(text,uuid,uuid,jsonb) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.portfolio_gravar_propostas(text,uuid,uuid,jsonb) TO service_role;